	// Sort helper for cross-unit rows (running table & modal)
	function sortCrossRows(rows, col, asc) {
		return rows.slice().sort(function (a, b) {
			var va, vb;
			if (col === 'name') {
				va = (a[a._unit.nameField] || a.name || '').toLowerCase();
				vb = (b[b._unit.nameField] || b.name || '').toLowerCase();
			} else if (col === 'unit') {
				va = a._unit.short.toLowerCase(); vb = b._unit.short.toLowerCase();
			} else if (col === 'status') {
				va = (a[a._unit.status_field] || '').toLowerCase();
				vb = (b[b._unit.status_field] || '').toLowerCase();
			} else {
				va = a.creation || ''; vb = b.creation || '';
			}
			return asc ? (va < vb ? -1 : va > vb ? 1 : 0) : (va > vb ? -1 : va < vb ? 1 : 0);
		});
	}

	// Sortable thead for cross-unit tables
	function crossTableHead(sortCol, sortAsc) {
		var cols = [
			{ key: '', label: '#' },
			{ key: 'name', label: 'Name' },
			{ key: 'unit', label: 'Unit' },
			{ key: 'status', label: 'Status' },
			{ key: 'applied', label: 'Applied' }
		];
		return '<thead><tr>' + cols.map(function (c) {
			if (!c.key) return '<th>#</th>';
			var on = sortCol === c.key;
			var arr = on ? (sortAsc ? '&#9650;' : '&#9660;') : '&#9650;';
			return '<th class="rd-th-sort' + (on ? ' rd-sort-on' : '') + '" data-col="' + c.key + '">' +
				c.label + '<span class="rd-sort-arr">' + arr + '</span></th>';
		}).join('') + '</tr></thead>';
	}
